package studio.jiayu.neo;
import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.net.Uri;
import android.os.*;
import android.text.InputType;
import android.widget.*;
import java.io.*;
import java.net.*;
import java.security.*;
import java.util.*;
import org.json.*;

/** Native GitHub updater. Tokens never enter a WebView, redirect, APK or export. */
final class AppUpdater {
 static final String REPO="JiayuStudio/stepx-neo-studio",KEY="github-updates";
 final MainActivity a;final android.content.SharedPreferences prefs;volatile boolean busy,cancelled;volatile HttpURLConnection connection;
 AlertDialog panel;TextView status;Button check,download,install;UpdateRelease release;File ready;boolean foreground=true;String installedVersion;
 AppUpdater(MainActivity activity){a=activity;prefs=a.getSharedPreferences("updates",0);try{installedVersion=a.getPackageManager().getPackageInfo(a.getPackageName(),0).versionName;}catch(Exception e){installedVersion="0.0.0";}new File(a.getCacheDir(),"update.part").delete();}
 void show(){if(panel!=null&&panel.isShowing())return;LinearLayout body=new LinearLayout(a);body.setOrientation(1);int pad=a.dp(18);body.setPadding(pad,a.dp(6),pad,0);status=new TextView(a);status.setTextSize(13);status.setText("当前版本 "+installedVersion+"\n更新源："+REPO+"\n只检查正式Release及其APK；源码提交不代表可安装更新。\n"+(a.vault.has(KEY)?"已保存GitHub访问令牌":"公开仓库可直接检查；私有仓库需要只读令牌"));body.addView(status);
  check=new Button(a);check.setText("检查更新");body.addView(check);check.setOnClickListener(v->check(false));download=new Button(a);download.setText("下载更新");body.addView(download);download.setVisibility(android.view.View.GONE);download.setOnClickListener(v->confirmDownload());install=new Button(a);install.setText("安装已下载的更新");body.addView(install);install.setVisibility(ready!=null?android.view.View.VISIBLE:android.view.View.GONE);install.setOnClickListener(v->install());
  CheckBox auto=new CheckBox(a);auto.setText("启动时检查（最多每天一次）");auto.setChecked(prefs.getBoolean("auto",false));body.addView(auto);auto.setOnCheckedChangeListener((v,on)->prefs.edit().putBoolean("auto",on).apply());Button settings=new Button(a);settings.setText("GitHub访问设置");body.addView(settings);settings.setOnClickListener(v->credentials());Button site=new Button(a);site.setText("打开版本页");body.addView(site);site.setOnClickListener(v->a.openExternal(Uri.parse(release==null?"https://github.com/"+REPO+"/releases":release.url)));
  ScrollView sc=new ScrollView(a);sc.addView(body);panel=new AlertDialog.Builder(a).setTitle("检查更新").setView(sc).setNegativeButton("关闭",(d,w)->cancel()).create();panel.setOnCancelListener(d->cancel());panel.show();check.setEnabled(!busy);if(release!=null){status("发现版本 "+release.version+"（当前 "+installedVersion+"）\n\n"+release.notes);download.setVisibility(android.view.View.VISIBLE);download.setEnabled(!busy);}
 }
 void credentials(){if(busy){a.toast("请先等待检查或下载结束");return;}EditText input=new EditText(a);input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);input.setHint("留空保留已有令牌");input.setImportantForAutofill(android.view.View.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS);LinearLayout box=new LinearLayout(a);box.setOrientation(1);box.setPadding(a.dp(20),a.dp(8),a.dp(20),0);TextView hint=new TextView(a);hint.setText("私有仓库需要GitHub fine-grained token：仅选择 "+REPO+"，Contents只读。\n令牌由Android Keystore加密，只发送到api.github.com，不进入网页、日志或项目导出。\n"+(a.vault.has(KEY)?"当前已保存；留空保留。":"当前未配置。"));box.addView(hint);box.addView(input);
  AlertDialog d=new AlertDialog.Builder(a).setTitle("GitHub只读访问").setView(box).setPositiveButton("保存",null).setNeutralButton("清除令牌",(x,w)->{a.vault.remove(KEY);status("已清除GitHub令牌");}).setNegativeButton("取消",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{try{String token=input.getText().toString().trim();if(!token.isEmpty()){if(token.length()>512||!token.matches("[A-Za-z0-9_]+"))throw new Exception("令牌格式无效");a.vault.put(KEY,token);}input.setText("");status("访问设置已保存，可以检查更新");d.dismiss();}catch(Exception e){input.setError("无法保存，请检查令牌格式");}}));d.show();d.getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_SECURE);
 }
 void automatic(){if(prefs.getBoolean("auto",false)&&System.currentTimeMillis()-prefs.getLong("lastAttempt",0)>24*60*60*1000L)check(true);}
 void status(String message){a.runOnUiThread(()->{if(status!=null)status.setText(message);});}
 boolean canRun(){return !a.link.running&&a.active==null&&!a.building&&!IntegrationActivity.busy;}
 void check(boolean quiet){if(busy)return;if(!canRun()){if(!quiet)a.toast("请先结束当前AI、联动或构建任务");return;}busy=true;cancelled=false;release=null;ready=null;if(check!=null)check.setEnabled(false);if(download!=null)download.setVisibility(android.view.View.GONE);if(install!=null)install.setVisibility(android.view.View.GONE);status("正在检查GitHub正式版本…");prefs.edit().putLong("lastAttempt",System.currentTimeMillis()).apply();
  new Thread(()->{try{String token=a.vault.get(KEY);HttpURLConnection c=open("https://api.github.com/repos/"+REPO+"/releases/latest",token,"application/vnd.github+json");JSONObject data;try(InputStream in=c.getInputStream()){data=new JSONObject(new String(read(in,1024*1024),"UTF-8"));}finally{c.disconnect();connection=null;}UpdateRelease found=UpdateRelease.parse(data,REPO);if(cancelled)return;int cmp=UpdateRelease.compare(found.version,installedVersion);prefs.edit().putLong("lastSuccess",System.currentTimeMillis()).putString("latest",found.version).apply();a.runOnUiThread(()->{if(cancelled||a.isDestroyed())return;if(cmp>0){release=found;if(quiet&&foreground){show();}status("发现新版本 "+found.version+"（当前 "+installedVersion+"）\n大小 "+(found.size/1024)+" KB\n\n"+found.notes);if(download!=null)download.setVisibility(android.view.View.VISIBLE);}else status("当前 "+installedVersion+"，仓库最新正式版本 "+found.version+"。\n"+(cmp==0?"已是最新版本。":"当前版本高于仓库正式版本，不进行降级。"));});
  }catch(Exception e){if(!cancelled)status(failure(e));}finally{busy=false;a.runOnUiThread(()->{if(check!=null)check.setEnabled(true);});}},"neo-update-check").start();
 }
 void confirmDownload(){if(release==null||busy)return;if(!canRun()){a.toast("请先结束当前任务");return;}UpdateRelease chosen=release;new AlertDialog.Builder(a).setTitle("下载 "+chosen.version).setMessage("将从GitHub下载 "+chosen.size/1024+" KB。下载后核对SHA-256、包名、版本和签名，再由Android确认安装；不会自动卸载应用。").setPositiveButton("下载",(d,w)->download(chosen)).setNegativeButton("取消",null).show();}
 void download(UpdateRelease chosen){busy=true;cancelled=false;ready=null;if(check!=null)check.setEnabled(false);if(download!=null)download.setEnabled(false);File part=new File(a.getCacheDir(),"update.part");
  new Thread(()->{try{HttpURLConnection c=open("https://api.github.com/repos/"+REPO+"/releases/assets/"+chosen.assetId,a.vault.get(KEY),"application/octet-stream");MessageDigest digest=MessageDigest.getInstance("SHA-256");long count=0,last=0;try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(part)){byte[] buf=new byte[32768];int n;while((n=in.read(buf))!=-1){if(cancelled)throw new IOException("cancelled");count+=n;if(count>chosen.size||count>100*1024*1024)throw new IOException("size");out.write(buf,0,n);digest.update(buf,0,n);if(System.currentTimeMillis()-last>250){last=System.currentTimeMillis();status("下载 "+chosen.version+" · "+(count*100/chosen.size)+"%\n关闭此窗口可取消。");}}}finally{c.disconnect();connection=null;}
   if(count!=chosen.size||!hex(digest.digest()).equals(chosen.sha))throw new IOException("digest");verify(part,chosen);if(cancelled)return;File dir=new File(a.getFilesDir(),"builds");dir.mkdirs();File dest=new File(dir,"self-update.apk");try(InputStream in=new FileInputStream(part);OutputStream out=new FileOutputStream(dest)){byte[]buf=new byte[32768];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}ready=dest;a.runOnUiThread(()->{if(cancelled||a.isDestroyed())return;status("已下载 "+chosen.version+"，SHA-256、包名、版本及签名核对通过。\n点击安装后仍由Android确认。");if(install!=null)install.setVisibility(android.view.View.VISIBLE);});
  }catch(Exception e){if(!cancelled)status(failure(e));}finally{part.delete();busy=false;a.runOnUiThread(()->{if(check!=null)check.setEnabled(true);if(download!=null)download.setEnabled(true);});}},"neo-update-download").start();
 }
 void verify(File f,UpdateRelease chosen)throws Exception{if(!new com.android.apksig.ApkVerifier.Builder(f).setMinCheckedPlatformVersion(30).build().verify().isVerified())throw new IOException("signature");PackageManager pm=a.getPackageManager();PackageInfo apk=pm.getPackageArchiveInfo(f.getAbsolutePath(),PackageManager.GET_SIGNING_CERTIFICATES),current=pm.getPackageInfo(a.getPackageName(),PackageManager.GET_SIGNING_CERTIFICATES);if(apk==null||!a.getPackageName().equals(apk.packageName))throw new IOException("package");if(!chosen.version.equals(apk.versionName)||apk.getLongVersionCode()<=current.getLongVersionCode())throw new IOException("version");if((apk.applicationInfo.flags&ApplicationInfo.FLAG_DEBUGGABLE)!=0)throw new IOException("debug");if(!signers(apk).equals(signers(current)))throw new IOException("signature");}
 static Set<String> signers(PackageInfo p)throws Exception{if(p.signingInfo==null)throw new IOException("signature");Set<String> out=new HashSet<>();for(android.content.pm.Signature s:p.signingInfo.getApkContentsSigners())out.add(hex(MessageDigest.getInstance("SHA-256").digest(s.toByteArray())));if(out.isEmpty())throw new IOException("signature");return out;}
 void install(){if(ready==null||release==null||busy)return;if(!canRun()){a.toast("请先结束当前任务再安装");return;}busy=true;cancelled=false;File file=ready;UpdateRelease chosen=release;install.setEnabled(false);check.setEnabled(false);download.setEnabled(false);status("正在复核安装包…");new Thread(()->{try{MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[]b=new byte[32768];int n;while((n=in.read(b))!=-1){if(cancelled)return;digest.update(b,0,n);}}if(file.length()!=chosen.size||!hex(digest.digest()).equals(chosen.sha))throw new IOException("digest");verify(file,chosen);a.runOnUiThread(()->{if(cancelled||a.isDestroyed())return;if(!canRun()){status("请先结束当前任务，再点击安装");return;}try{launchInstall();}catch(Exception e){status("无法打开系统安装器，请稍后重试。");}});}catch(Exception e){ready=null;a.runOnUiThread(()->{install.setVisibility(android.view.View.GONE);status(failure(e));});}finally{busy=false;a.runOnUiThread(()->{install.setEnabled(true);check.setEnabled(true);download.setEnabled(true);});}},"neo-update-verify").start();}
 void launchInstall(){if(!a.getPackageManager().canRequestPackageInstalls()){new AlertDialog.Builder(a).setTitle("允许安装应用更新").setMessage("请在Android设置中允许此来源安装应用，然后返回点击“安装已下载的更新”。").setPositiveButton("打开系统设置",(d,w)->a.startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+a.getPackageName())))).setNegativeButton("取消",null).show();return;}a.startActivity(new Intent(Intent.ACTION_VIEW).setDataAndType(Uri.parse("content://studio.jiayu.neo.builds/self-update.apk"),"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}
 HttpURLConnection open(String address,String token,String accept)throws Exception{for(int hop=0;hop<4;hop++){if(cancelled)throw new IOException("cancelled");URL url=new URL(address);String host=url.getHost();if(!"https".equals(url.getProtocol())||url.getUserInfo()!=null||(url.getPort()!=-1&&url.getPort()!=443)||!(host.equals("api.github.com")||host.equals("release-assets.githubusercontent.com")||host.equals("objects.githubusercontent.com")))throw new IOException("redirect");HttpURLConnection c=(HttpURLConnection)url.openConnection();connection=c;c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setRequestProperty("User-Agent","StepXNeoStudio-Updater");c.setRequestProperty("Accept",accept);c.setRequestProperty("Accept-Encoding","identity");if(host.equals("api.github.com")){c.setRequestProperty("X-GitHub-Api-Version","2022-11-28");if(hop==0&&!token.isEmpty())c.setRequestProperty("Authorization","Bearer "+token);}int code=c.getResponseCode();if(code==301||code==302||code==303||code==307||code==308){String next=c.getHeaderField("Location");c.disconnect();if(next==null)throw new IOException("redirect");address=new URL(url,next).toString();continue;}if(code!=200){c.disconnect();throw new IOException("HTTP "+code);}return c;}throw new IOException("redirect");}
 byte[] read(InputStream in,int limit)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[]b=new byte[8192];int n;while((n=in.read(b))!=-1){if(cancelled)throw new IOException("cancelled");if(out.size()+n>limit)throw new IOException("size");out.write(b,0,n);}return out.toByteArray();}
 static String hex(byte[] bytes){StringBuilder b=new StringBuilder();for(byte x:bytes)b.append(String.format(java.util.Locale.ROOT,"%02x",x&255));return b.toString();}
 String failure(Exception e){String m=e.getMessage();if("HTTP 404".equals(m))return "无法读取更新：仓库尚无正式版本，或私有仓库令牌缺失/无权访问。请检查GitHub访问设置。";if("HTTP 401".equals(m))return "GitHub令牌无效或已过期，请更新访问设置。";if("HTTP 403".equals(m)||"HTTP 429".equals(m))return "GitHub拒绝访问或请求过于频繁，请检查权限或稍后重试。";if(Arrays.asList("digest","size","package","version","signature","debug","redirect").contains(m))return "更新校验未通过（"+m+"），已停止安装，请重新检查更新。";return "更新未完成："+(e instanceof java.net.SocketTimeoutException?"网络超时，请稍后重试":e instanceof JSONException?"版本信息格式不符合要求":e instanceof IOException?"网络或文件读取失败，请稍后重试":"版本未提供可验证的正式安装包")+"。";}
 void cancel(){cancelled=true;HttpURLConnection c=connection;if(c!=null)c.disconnect();}
 void destroy(){cancel();if(panel!=null)panel.dismiss();}
}
